const email = $input.first().json;
const startTime = Date.now();

const EXTRACTION_PROMPT = `You are an expert B2B quote request parser for an industrial steel and metals distributor.
Extract structured data from the following quote request email.

IMPORTANT RULES:
- The email is in French (industrial B2B context)
- Product descriptions may contain jargon: "inox" = stainless steel, "Ø" = diameter, "lg" = length
- Common abbreviations: 304L, 316L (steel grades), HM (hexagonal), BLN (bolt), DN (nominal diameter)
- Quantities may use French notation: "200 pcs", "5 barres", "10 ml" (mètres linéaires)
- If information is not mentioned, use null (do NOT invent data)
- Extract ALL products mentioned, even if descriptions are vague
- References may look like: "TUBE-INOX-304L-25x1.5-6M" or "BHM-M12x50"
- For client_name, extract the company name if available, otherwise the person name
- For client_email, use the "from" field of the email

Return a JSON object with this exact schema:
{
  "client_name": "string or null",
  "client_email": "string or null",
  "products": [
    {
      "description": "product description as written by client",
      "reference": "product code/reference if mentioned, else null",
      "quantity": "quantity with unit as written",
      "specs": "any specs (dimensions, material, grade, finish) or null"
    }
  ],
  "delivery_date": "delivery date if mentioned, else null",
  "notes": "any additional context or requirements, else null"
}`;

const emailText = `From: ${email.from}\nSubject: ${email.subject}\nDate: ${email.date}\n\n${email.body}`;

try {
  const response = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://api.openai.com/v1/chat/completions',
    headers: {
      'Authorization': `Bearer ${$env.OPENAI_API_KEY}`,
      'Content-Type': 'application/json'
    },
    body: {
      model: 'gpt-4o',
      response_format: { type: 'json_object' },
      temperature: 0,
      messages: [
        { role: 'system', content: EXTRACTION_PROMPT },
        { role: 'user', content: emailText }
      ]
    }
  });

  const extracted = JSON.parse(response.choices[0].message.content);
  if (!Array.isArray(extracted.products)) extracted.products = [];

  return [{ json: {
    ...email,
    extraction: extracted,
    _extraction_ms: Date.now() - startTime
  }}];
} catch (err) {
  return [{ json: { ...email, _error: `Extraction: ${err.message}` }}];
}

// Product search via Qdrant HTTP API (no embedding — use pre-computed dense vectors not available here)
// NOTE: This n8n version uses Qdrant scroll with payload filter (keyword matching on default_code or name)
// For full hybrid search with BGE-M3 embeddings, use the Python script (e2e-quote-pipeline.py)

const data = $input.first().json;
if (data._error) return [{ json: data }];

const extraction = data.extraction;
const matchedProducts = [];

for (const product of extraction.products) {
  // Try exact reference match if reference provided
  let matched = null;
  if (product.reference) {
    try {
      const scrollResp = await this.helpers.httpRequest({
        method: 'POST',
        url: 'http://qdrant:6333/collections/products/points/scroll',
        headers: { 'Content-Type': 'application/json' },
        body: {
          filter: {
            should: [
              { key: 'default_code', match: { value: product.reference } },
              { key: 'default_code', match: { value: product.reference.toUpperCase() } }
            ]
          },
          limit: 1,
          with_payload: true
        }
      });
      if (scrollResp.result && scrollResp.result.points && scrollResp.result.points.length > 0) {
        const pt = scrollResp.result.points[0];
        matched = {
          odoo_product_id: pt.id,
          name: pt.payload.name || '',
          default_code: pt.payload.default_code || '',
          list_price: pt.payload.list_price || 0,
          match_type: 'exact_ref'
        };
      }
    } catch (e) { /* fallback to scroll search below */ }
  }

  // Parse quantity
  let qty = 1;
  if (product.quantity) {
    const m = String(product.quantity).match(/[\d]+(?:[.,]\d+)?/);
    if (m) qty = parseFloat(m[0].replace(',', '.'));
  }

  matchedProducts.push({
    description: product.description || '',
    reference: product.reference,
    quantity: qty,
    match: matched,
    _note: matched ? 'exact ref match via Qdrant payload filter' : 'no match (n8n version lacks embedding support — use Python script for hybrid search)'
  });
}

return [{ json: {
  ...data,
  matched_products: matchedProducts
}}];

// Odoo JSON-RPC: Find or create customer, then create draft quote
const data = $input.first().json;
if (data._error) return [{ json: data }];

const extraction = data.extraction;
const matchedProducts = data.matched_products;

// --- Odoo JSON-RPC helpers ---
const ODOO_URL = 'http://odoo:8069';
const DB = 'odoo_db';
const LOGIN = 'admin';
const PASSWORD = 'admin';

async function odooAuth() {
  const resp = await this.helpers.httpRequest({
    method: 'POST',
    url: `${ODOO_URL}/web/session/authenticate`,
    headers: { 'Content-Type': 'application/json' },
    body: { jsonrpc: '2.0', params: { db: DB, login: LOGIN, password: PASSWORD } },
    returnFullResponse: true
  });
  const cookies = resp.headers['set-cookie'] || [];
  const sessionCookie = cookies.find(c => c.startsWith('session_id='));
  const sessionId = sessionCookie ? sessionCookie.split('=')[1].split(';')[0] : '';
  return { uid: resp.body.result.uid, sessionId };
}

async function odooRPC(sessionId, uid, model, method, args, kwargs) {
  const resp = await this.helpers.httpRequest({
    method: 'POST',
    url: `${ODOO_URL}/jsonrpc`,
    headers: {
      'Content-Type': 'application/json',
      'Cookie': `session_id=${sessionId}`
    },
    body: {
      jsonrpc: '2.0',
      method: 'call',
      params: {
        service: 'object',
        method: 'execute_kw',
        args: [DB, uid, PASSWORD, model, method, args, kwargs || {}]
      }
    }
  });
  if (resp.error) throw new Error(`Odoo: ${JSON.stringify(resp.error)}`);
  return resp.result;
}

try {
  const { uid, sessionId } = await odooAuth.call(this);

  // Find or create customer
  let partnerId = null;
  if (extraction.client_email) {
    const ids = await odooRPC.call(this, sessionId, uid, 'res.partner', 'search',
      [[['email', '=', extraction.client_email]]]);
    if (ids && ids.length) partnerId = ids[0];
  }
  if (!partnerId && extraction.client_name) {
    const ids = await odooRPC.call(this, sessionId, uid, 'res.partner', 'search',
      [[['name', 'ilike', extraction.client_name]]]);
    if (ids && ids.length) partnerId = ids[0];
  }
  if (!partnerId) {
    partnerId = await odooRPC.call(this, sessionId, uid, 'res.partner', 'create',
      [{ name: extraction.client_name || extraction.client_email || 'Unknown', email: extraction.client_email || '' }]);
  }

  // Build order lines (only for matched products)
  const orderLines = matchedProducts
    .filter(p => p.match !== null)
    .map(p => [0, 0, {
      product_id: p.match.odoo_product_id,
      product_uom_qty: p.quantity,
      price_unit: p.match.list_price,
      name: p.description
    }]);

  if (orderLines.length === 0) {
    return [{ json: { ...data, _error: 'No products matched — cannot create quote' }}];
  }

  // Create draft sale.order
  const values = { partner_id: partnerId, order_line: orderLines };
  if (extraction.delivery_date) values.commitment_date = extraction.delivery_date;
  const saleOrderId = await odooRPC.call(this, sessionId, uid, 'sale.order', 'create', [values]);

  return [{ json: {
    _scenario: data._scenario,
    _email_from: data.from,
    _email_subject: data.subject,
    sale_order_id: saleOrderId,
    partner_id: partnerId,
    line_count: orderLines.length,
    total_products: extraction.products.length,
    matched_count: matchedProducts.filter(p => p.match).length,
    _extraction_ms: data._extraction_ms,
    status: 'PASS'
  }}];
} catch (err) {
  return [{ json: { ...data, _error: `Odoo: ${err.message}` }}];
}

// Aggregate results from all scenarios
const items = $input.all();
const results = items.map(i => i.json);
const passed = results.filter(r => r.status === 'PASS').length;
const failed = results.filter(r => r._error).length;

return [{ json: {
  summary: {
    total: results.length,
    passed,
    failed,
    scenarios: results.map(r => ({
      scenario: r._scenario || r._email_from,
      sale_order_id: r.sale_order_id,
      partner_id: r.partner_id,
      lines: r.line_count,
      status: r.status || 'FAIL',
      error: r._error || null
    }))
  }
}}];
